package br.com.estudario.data.transfer

import androidx.room.withTransaction
import br.com.estudario.data.local.*
import org.json.JSONArray
import org.json.JSONObject

/** Nome antigo do app; backups gerados antes da troca continuam sendo aceitos na restauração. */
private const val BACKUP_FORMAT = "estudario-backup"
private val ACCEPTED_BACKUP_FORMATS = setOf(BACKUP_FORMAT, "meu-concurso-backup", "backup")

class BackupService(private val db: AppDatabase) {
    private val dao = db.dao()

    suspend fun export(): String {
        val questions = dao.questionsOnce()
        val root = JSONObject()
            .put("format", BACKUP_FORMAT)
            .put("version", 5)
            .put("exportedAt", System.currentTimeMillis())
            .put("competitions", JSONArray(dao.competitionsOnce().map { JSONObject().put("id", it.id).put("name", it.name).put("primary", it.isPrimary).put("createdAt", it.createdAt).putNullable("externalId", it.externalId) }))
            .put("subjects", JSONArray(dao.subjectsOnce().map { JSONObject().put("id", it.id).put("competitionId", it.competitionId).put("name", it.name).put("position", it.position).putNullable("externalId", it.externalId) }))
            .put("topics", JSONArray(dao.topicsOnce().map { JSONObject().put("id", it.id).put("subjectId", it.subjectId).putNullable("parentTopicId", it.parentTopicId).put("title", it.title).put("description", it.description).put("position", it.position).put("status", it.status.name).putNullable("firstStudiedAt", it.firstStudiedAt).putNullable("lastStudiedAt", it.lastStudiedAt).putNullable("lastReviewedAt", it.lastReviewedAt).put("notes", it.notes).put("priority", it.priority.name).putNullable("externalId", it.externalId).put("contentOriginType", it.contentOriginType.name).putNullable("scopeCovers", it.scopeCovers).putNullable("scopeExcludes", it.scopeExcludes) }))
            .put("summaries", JSONArray(dao.summariesOnce().map { JSONObject().put("id", it.id).put("topicId", it.topicId).put("title", it.title).put("markdown", it.markdown).put("favorite", it.isFavorite).put("ownNotes", it.ownNotes).putNullable("externalId", it.externalId).put("createdAt", it.createdAt).put("updatedAt", it.updatedAt).put("kind", it.kind.name) }))
            .put("snippets", JSONArray(dao.snippetsOnce().map { JSONObject().put("id", it.id).put("topicId", it.topicId).put("kind", it.kind.name).put("text", it.text).put("favorite", it.isFavorite).putNullable("externalId", it.externalId).put("position", it.position).put("createdAt", it.createdAt).put("updatedAt", it.updatedAt) }))
            .put("theories", JSONArray(dao.theoriesOnce().map { JSONObject().put("id", it.id).put("topicId", it.topicId).put("title", it.title).put("markdown", it.markdown).putNullable("externalId", it.externalId).put("lastReadBlock", it.lastReadBlock).put("createdAt", it.createdAt).put("updatedAt", it.updatedAt) }))
            .put("theoryMarks", JSONArray(dao.theoryMarksOnce().map { JSONObject().put("id", it.id).put("theoryId", it.theoryId).put("blockIndex", it.blockIndex).put("quote", it.quote).put("note", it.note).put("color", it.color).put("createdAt", it.createdAt) }))
            .put("contentSources", JSONArray(dao.sourcesOnce().map { JSONObject().put("id", it.id).putNullable("topicId", it.topicId).put("packageId", it.packageId).put("kind", it.kind.name).put("title", it.title).put("publisher", it.publisher).put("reference", it.reference).putNullable("url", it.url).put("accessedAt", it.accessedAt).putNullable("externalId", it.externalId).put("createdAt", it.createdAt) }))
            .put("questions", JSONArray(questions.map { item -> JSONObject().put("id", item.question.id).put("topicId", item.question.topicId).putNullable("externalId", item.question.externalId).putNullable("board", item.question.board).putNullable("agency", item.question.agency).putNullable("year", item.question.year).putNullable("difficulty", item.question.difficulty?.name).putNullable("source", item.question.source).put("statement", item.question.statement).put("explanation", item.question.explanation).put("notes", item.question.notes).put("tags", item.question.tagsText).put("importedAt", item.question.importedAt).put("answerCount", item.question.answerCount).put("correctCount", item.question.correctCount).put("errorCount", item.question.errorCount).putNullable("lastAnswer", item.question.lastAnswer).putNullable("lastAnsweredAt", item.question.lastAnsweredAt).put("favorite", item.question.isFavorite).put("questionSourceType", item.question.questionSourceType.name).putNullable("sourceId", item.question.sourceId).putNullable("sourceUrl", item.question.sourceUrl).putNullable("normalizedHash", item.question.normalizedHash).putNullable("reviewAnchor", item.question.reviewAnchor).putNullable("errorConceptExternalId", item.question.errorConceptExternalId).put("options", JSONArray(item.options.map { JSONObject().put("id", it.id).put("key", it.key).put("text", it.text).put("correct", it.isCorrect).put("position", it.position) })) }))
            .put("attempts", JSONArray(dao.attemptsOnce().map { JSONObject().put("id", it.id).put("questionId", it.questionId).put("selectedKey", it.selectedKey).put("correct", it.correct).put("answeredAt", it.answeredAt).putNullable("sessionId", it.sessionId) }))
            .put("errors", JSONArray(dao.errorsOnce().map { JSONObject().put("id", it.id).put("questionId", it.questionId).put("errorCount", it.errorCount).put("retryCorrectCount", it.retryCorrectCount).put("firstErrorAt", it.firstErrorAt).put("lastErrorAt", it.lastErrorAt).putNullable("lastReviewedAt", it.lastReviewedAt).put("comment", it.comment).put("concept", it.concept).put("pending", it.pending).putNullable("selectedAnswer", it.selectedAnswer).putNullable("correctAnswer", it.correctAnswer).put("status", it.status.name).put("retryStreak", it.retryStreak).putNullable("nextRetryAt", it.nextRetryAt) }))
            .put("errorConcepts", JSONArray(dao.errorConceptsOnce().map { JSONObject().put("id", it.id).put("topicId", it.topicId).put("title", it.title).put("summary", it.summary).put("favorite", it.isFavorite).putNullable("externalId", it.externalId).put("createdAt", it.createdAt).put("updatedAt", it.updatedAt).put("errorCount", it.errorCount).put("correctAfterErrorCount", it.correctAfterErrorCount).putNullable("lastErrorAt", it.lastErrorAt).putNullable("lastReviewedAt", it.lastReviewedAt).put("priority", it.priority.name).put("mastered", it.mastered) }))
            .put("errorConceptEntries", JSONArray(dao.errorConceptEntriesOnce().map { JSONObject().put("conceptId", it.conceptId).put("errorEntryId", it.errorEntryId) }))
            .put("reviews", JSONArray(dao.reviewsOnce().map { JSONObject().put("id", it.id).put("topicId", it.topicId).put("stage", it.stage).put("dueAt", it.dueAt).putNullable("completedAt", it.completedAt).putNullable("ignoredAt", it.ignoredAt).putNullable("perceivedDifficulty", it.perceivedDifficulty?.name).put("questionCorrect", it.questionCorrect).put("questionTotal", it.questionTotal) }))
            .put("reviewHistory", JSONArray(dao.reviewHistoryOnce().map { JSONObject().put("id", it.id).put("topicId", it.topicId).put("reviewedAt", it.reviewedAt) }))
            .put("reviewSessions", JSONArray(dao.reviewSessionsOnce().map { JSONObject().put("id", it.id).put("reviewId", it.reviewId).put("topicId", it.topicId).put("startedAt", it.startedAt).put("completedAt", it.completedAt).put("recalled", it.recalled).put("forgotten", it.forgotten).put("questionCorrect", it.questionCorrect).put("questionTotal", it.questionTotal).put("difficulty", it.perceivedDifficulty.name) }))
            .put("queue", JSONArray(dao.queueOnce().map { JSONObject().put("id", it.id).put("topicId", it.topicId).put("position", it.position).put("paused", it.paused).put("enqueuedAt", it.enqueuedAt).put("postponements", it.postponements) }))
            .put("queueEvents", JSONArray(dao.queueEventsOnce().map { JSONObject().put("id", it.id).put("topicId", it.topicId).put("type", it.type.name).put("occurredAt", it.occurredAt).put("reason", it.reason) }))
            .put("sessions", JSONArray(dao.sessionsOnce().map { JSONObject().put("id", it.id).put("topicId", it.topicId).put("startedAt", it.startedAt).put("completedAt", it.completedAt).putNullable("competitionId", it.competitionId).putNullable("subjectId", it.subjectId).put("durationSeconds", it.durationSeconds).put("questionCount", it.questionCount).put("correctCount", it.correctCount).put("wrongCount", it.wrongCount).put("notes", it.notes).putNullable("sourcePackageId", it.sourcePackageId) }))
            .put("questionSessions", JSONArray(dao.questionSessionsOnce().map { JSONObject().put("id", it.id).put("type", it.type.name).put("startedAt", it.startedAt).put("completedAt", it.completedAt).put("durationSeconds", it.durationSeconds).put("questionCount", it.questionCount).put("correctCount", it.correctCount).put("subjectIds", it.subjectIdsText).put("topicIds", it.topicIdsText) }))
            .put("importPackages", JSONArray(dao.importPackagesOnce().map { JSONObject().put("id", it.id).put("packageId", it.packageId).put("schemaVersion", it.schemaVersion).put("importedAt", it.importedAt).put("contentHash", it.contentHash).put("fileName", it.fileName).put("createdCount", it.createdCount).put("updatedCount", it.updatedCount).put("ignoredCount", it.ignoredCount) }))
            .put("notes", JSONArray(dao.notesOnce().map { JSONObject().put("id", it.id).putNullable("topicId", it.topicId).putNullable("questionId", it.questionId).put("text", it.text).put("createdAt", it.createdAt) }))
            .put("tags", JSONArray(dao.tagsOnce().map { JSONObject().put("id", it.id).put("name", it.name) }))
            .put("questionTags", JSONArray(dao.questionTagsOnce().map { JSONObject().put("questionId", it.questionId).put("tagId", it.tagId) }))
        PlannerBackupCodec.write(db, root)
        return root.toString(2)
    }

    suspend fun restore(text: String) = db.withTransaction {
        val root = try { JSONObject(text) } catch (_: Exception) { throw IllegalArgumentException("Backup JSON inválido.") }
        // Aceita o formato antigo para não invalidar backups feitos antes da troca de nome.
        if (root.optString("format") !in ACCEPTED_BACKUP_FORMATS || root.optInt("version") !in 1..5) throw IllegalArgumentException("Formato ou versão de backup não suportado.")
        val competitions = root.array("competitions").objects().map { CompetitionEntity(it.getLong("id"), it.getString("name"), it.getBoolean("primary"), it.getLong("createdAt"), it.optNullableString("externalId")) }
        val subjects = root.array("subjects").objects().map { SubjectEntity(it.getLong("id"), it.getLong("competitionId"), it.getString("name"), it.getInt("position"), it.optNullableString("externalId")) }
        val topics = root.array("topics").objects().map { TopicEntity(it.getLong("id"), it.getLong("subjectId"), it.optLongOrNull("parentTopicId"), it.getString("title"), it.getString("description"), it.getInt("position"), TopicStatus.valueOf(it.getString("status")), it.optLongOrNull("firstStudiedAt"), it.optLongOrNull("lastStudiedAt"), it.optLongOrNull("lastReviewedAt"), it.getString("notes"), Priority.valueOf(it.getString("priority")), it.optNullableString("externalId"), ContentOriginType.valueOf(it.optString("contentOriginType", "EDITAL")), it.optNullableString("scopeCovers"), it.optNullableString("scopeExcludes")) }
        val summaries = root.array("summaries").objects().map { SummaryEntity(it.getLong("id"), it.getLong("topicId"), it.getString("title"), it.getString("markdown"), it.getBoolean("favorite"), it.getString("ownNotes"), it.optNullableString("externalId"), it.getLong("createdAt"), it.getLong("updatedAt"), SummaryKind.valueOf(it.optString("kind", "COMPLETO"))) }
        val snippets = root.array("snippets").objects().map { TopicSnippetEntity(it.getLong("id"), it.getLong("topicId"), SnippetKind.valueOf(it.getString("kind")), it.getString("text"), it.optBoolean("favorite"), it.optNullableString("externalId"), it.optInt("position"), it.optLong("createdAt", System.currentTimeMillis()), it.optLong("updatedAt", System.currentTimeMillis())) }
        val theories = root.array("theories").objects().map { TheoryDocumentEntity(it.getLong("id"), it.getLong("topicId"), it.getString("title"), it.getString("markdown"), it.optNullableString("externalId"), it.optInt("lastReadBlock"), it.getLong("createdAt"), it.getLong("updatedAt")) }
        val theoryMarks = root.array("theoryMarks").objects().map { TheoryMarkEntity(it.getLong("id"), it.getLong("theoryId"), it.getInt("blockIndex"), it.getString("quote"), it.optString("note"), it.optInt("color"), it.getLong("createdAt")) }
        val contentSources = root.array("contentSources").objects().map {
            ContentSourceEntity(
                it.getLong("id"), it.optLongOrNull("topicId"), it.optString("packageId"),
                SourceKind.valueOf(it.optString("kind", "COMPLEMENTAR")), it.getString("title"),
                it.optString("publisher"), it.optString("reference"), it.optNullableString("url"),
                it.optString("accessedAt"), it.optNullableString("externalId"),
                it.optLong("createdAt", System.currentTimeMillis()),
            )
        }
        val questionsJson = root.array("questions").objects()
        val questions = questionsJson.map { QuestionEntity(it.getLong("id"), it.getLong("topicId"), it.optNullableString("externalId"), it.optNullableString("board"), it.optNullableString("agency"), it.optInt("year").takeIf { year -> year > 0 }, it.optNullableString("difficulty")?.let(Difficulty::valueOf), it.optNullableString("source"), it.getString("statement"), it.getString("explanation"), it.getString("notes"), it.getString("tags"), it.getLong("importedAt"), it.getInt("answerCount"), it.getInt("correctCount"), it.getInt("errorCount"), it.optNullableString("lastAnswer"), it.optLongOrNull("lastAnsweredAt"), it.getBoolean("favorite"), QuestionSourceType.valueOf(it.optString("questionSourceType", "AUTHORIAL")), it.optNullableString("sourceId"), it.optNullableString("sourceUrl"), it.optNullableString("normalizedHash"), it.optNullableString("reviewAnchor"), it.optNullableString("errorConceptExternalId")) }
        val options = questionsJson.flatMap { q -> q.array("options").objects().map { QuestionOptionEntity(it.getLong("id"), q.getLong("id"), it.getString("key"), it.getString("text"), it.getBoolean("correct"), it.getInt("position")) } }
        val attempts = root.array("attempts").objects().map { QuestionAttemptEntity(it.getLong("id"), it.getLong("questionId"), it.getString("selectedKey"), it.getBoolean("correct"), it.getLong("answeredAt"), it.optNullableString("sessionId")) }
        val errors = root.array("errors").objects().map { ErrorNotebookEntryEntity(it.getLong("id"), it.getLong("questionId"), it.getInt("errorCount"), it.getInt("retryCorrectCount"), it.getLong("firstErrorAt"), it.getLong("lastErrorAt"), it.optLongOrNull("lastReviewedAt"), it.getString("comment"), it.getString("concept"), it.getBoolean("pending"), it.optNullableString("selectedAnswer"), it.optNullableString("correctAnswer"), ErrorStatus.valueOf(it.optString("status", if (it.optBoolean("pending")) "NOVO" else "CORRIGIDO")), it.optInt("retryStreak"), it.optLongOrNull("nextRetryAt")) }
        val errorConcepts = root.array("errorConcepts").objects().map { ErrorConceptEntity(it.getLong("id"), it.getLong("topicId"), it.getString("title"), it.optString("summary"), it.optBoolean("favorite"), it.optNullableString("externalId"), it.optLong("createdAt", System.currentTimeMillis()), it.optLong("updatedAt", System.currentTimeMillis()), it.optInt("errorCount"), it.optInt("correctAfterErrorCount"), it.optLongOrNull("lastErrorAt"), it.optLongOrNull("lastReviewedAt"), Priority.valueOf(it.optString("priority", "NORMAL")), it.optBoolean("mastered")) }
        val errorConceptEntries = root.array("errorConceptEntries").objects().map { ErrorConceptEntryCrossRef(it.getLong("conceptId"), it.getLong("errorEntryId")) }
        val reviews = root.array("reviews").objects().map { ReviewScheduleEntity(it.getLong("id"), it.getLong("topicId"), it.getInt("stage"), it.getLong("dueAt"), it.optLongOrNull("completedAt"), it.optLongOrNull("ignoredAt"), it.optNullableString("perceivedDifficulty")?.let(ReviewDifficulty::valueOf), it.optInt("questionCorrect"), it.optInt("questionTotal")) }
        val history = root.array("reviewHistory").objects().map { ReviewHistoryEntity(it.getLong("id"), it.getLong("topicId"), it.getLong("reviewedAt")) }
        val reviewSessions = root.array("reviewSessions").objects().map { ReviewSessionEntity(it.getLong("id"), it.getLong("reviewId"), it.getLong("topicId"), it.getLong("startedAt"), it.getLong("completedAt"), it.optInt("recalled"), it.optInt("forgotten"), it.optInt("questionCorrect"), it.optInt("questionTotal"), ReviewDifficulty.valueOf(it.optString("difficulty", "NORMAL"))) }
        val queue = root.array("queue").objects().map { StudyQueueEntity(it.getLong("id"), it.getLong("topicId"), it.getInt("position"), it.getBoolean("paused"), it.optLong("enqueuedAt", System.currentTimeMillis()), it.optInt("postponements")) }
        val queueEvents = root.array("queueEvents").objects().map { QueueEventEntity(it.getLong("id"), it.getLong("topicId"), QueueEventType.valueOf(it.getString("type")), it.getLong("occurredAt"), it.optString("reason")) }
        val sessions = root.array("sessions").objects().map { StudySessionEntity(it.getLong("id"), it.getLong("topicId"), it.getLong("startedAt"), it.getLong("completedAt"), it.optLongOrNull("competitionId"), it.optLongOrNull("subjectId"), it.optLong("durationSeconds"), it.optInt("questionCount"), it.optInt("correctCount"), it.optInt("wrongCount"), it.optString("notes"), it.optNullableString("sourcePackageId")) }
        val questionSessions = root.array("questionSessions").objects().map { QuestionSessionEntity(it.getString("id"), QuestionSessionType.valueOf(it.getString("type")), it.getLong("startedAt"), it.getLong("completedAt"), it.getLong("durationSeconds"), it.getInt("questionCount"), it.getInt("correctCount"), it.optString("subjectIds"), it.optString("topicIds")) }
        val importPackages = root.array("importPackages").objects().map { ImportPackageEntity(it.getLong("id"), it.getString("packageId"), it.getInt("schemaVersion"), it.getLong("importedAt"), it.getString("contentHash"), it.optString("fileName"), it.optInt("createdCount"), it.optInt("updatedCount"), it.optInt("ignoredCount")) }
        val notes = root.array("notes").objects().map { UserNoteEntity(it.getLong("id"), it.optLongOrNull("topicId"), it.optLongOrNull("questionId"), it.getString("text"), it.getLong("createdAt")) }
        val tags = root.array("tags").objects().map { TagEntity(it.getLong("id"), it.getString("name")) }
        val questionTags = root.array("questionTags").objects().map { QuestionTagCrossRef(it.getLong("questionId"), it.getLong("tagId")) }

        dao.clearContentSources(); dao.clearQuestionTags(); dao.clearTags(); dao.clearNotes(); dao.clearImportPackages(); dao.clearQuestionSessions(); dao.clearQueueEvents(); dao.clearSessions(); dao.clearQueue(); dao.clearReviewHistory(); dao.clearReviewSessions(); dao.clearReviews(); dao.clearErrorConceptEntries(); dao.clearErrorConcepts(); dao.clearErrors(); dao.clearAttempts(); dao.clearQuestions(); dao.clearSnippets(); dao.clearSummaries(); dao.clearTheoryMarks(); dao.clearTheories(); dao.clearTopics(); dao.clearSubjects(); dao.clearCompetitions()
        dao.restoreCompetitions(competitions); dao.restoreSubjects(subjects); dao.restoreTopics(topics); dao.restoreSummaries(summaries); dao.restoreSnippets(snippets); dao.restoreTheories(theories); dao.restoreTheoryMarks(theoryMarks); dao.restoreQuestions(questions); dao.restoreOptions(options); dao.restoreAttempts(attempts); dao.restoreErrors(errors); dao.restoreErrorConcepts(errorConcepts); dao.restoreErrorConceptEntries(errorConceptEntries); dao.restoreReviews(reviews); dao.restoreReviewHistory(history); dao.restoreReviewSessions(reviewSessions); dao.restoreQueue(queue); dao.restoreSessions(sessions); dao.restoreQueueEvents(queueEvents); dao.restoreQuestionSessions(questionSessions); dao.restoreImportPackages(importPackages); dao.restoreNotes(notes); dao.restoreTags(tags); dao.restoreQuestionTags(questionTags); dao.restoreContentSources(contentSources)
        if (root.optInt("version") >= 5) PlannerBackupCodec.restore(db, root)
    }
}

private fun JSONObject.putNullable(key: String, value: Any?): JSONObject = put(key, value ?: JSONObject.NULL)
private fun JSONObject.optLongOrNull(key: String): Long? = if (!has(key) || isNull(key)) null else getLong(key)
private fun JSONObject.array(key: String): JSONArray = optJSONArray(key) ?: JSONArray()
